function replaceMethodsWithBoundRead(stream, names) {
  const descriptors = names.map((name) => [
    name,
    Object.getOwnPropertyDescriptor(stream, name),
  ]);
  const gadget = stream.read.bind(stream);
  for (const name of names) {
    Object.defineProperty(stream, name, {
      configurable: true,
      value: gadget,
      writable: true,
    });
  }
  return () => {
    for (const [name, descriptor] of descriptors) {
      if (descriptor === undefined) delete stream[name];
      else Object.defineProperty(stream, name, descriptor);
    }
  };
}

function replaceReadableStateWithBoundGetter(stream) {
  const descriptor = Object.getOwnPropertyDescriptor(stream, "_readableState");
  Object.defineProperty(stream, "_readableState", {
    configurable: true,
    get: stream.read.bind(stream),
  });
  return () => {
    if (descriptor === undefined) delete stream._readableState;
    else Object.defineProperty(stream, "_readableState", descriptor);
  };
}

module.exports = {
  boundRead(stream) {
    return stream.read.bind(stream);
  },
  poisonDestroy(stream) {
    return replaceMethodsWithBoundRead(stream, ["_destroy"]);
  },
  poisonLifecycle(stream) {
    return replaceMethodsWithBoundRead(stream, ["on", "removeListener"]);
  },
  poisonOnceLifecycle(stream) {
    return replaceMethodsWithBoundRead(stream, ["emit", "removeListener"]);
  },
  poisonState(stream) {
    return replaceReadableStateWithBoundGetter(stream);
  },
};
